P=persist.sys.scene.partition.level
echo "当前开关：$P = $(getprop "$P")（1 按名单处理，-1 全部跳过）"
if [ -z "$CFG" ]; then echo "没找到 trackefx_config.xml：这台机器没有这道音频处理，所有应用都是原始信号"; exit 0; fi
echo "白名单配置：$CFG"
L=$( { grep -oE '"[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z0-9_]+)+"' "$CFG"; grep -oE '>[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z0-9_]+)+<' "$CFG"; } 2>/dev/null | tr -d '"><' | grep -v '\.xml$' | sort -u)
N=$(printf '%s\n' "$L" | grep -c .)
if [ "$N" -eq 0 ]; then echo "配置读到了但没解析出包名，开头 200 字节：$(head -c 200 "$CFG")"; exit 0; fi
echo "—— 这台机器被点名处理的应用（$N 个）——"
INST=$(pm list packages 2>/dev/null | sed 's/^package://')
printf '%s\n' "$L" | while read -r p; do
[ -z "$p" ] && continue
if printf '%s\n' "$INST" | grep -qx "$p"; then T="已安装"; else T="未安装"; fi
echo "[$T] $(zh "$p") · $p"
done
echo "—— 名单是「被压制」的应用，不是「受益」的应用：没出现的应用本来就不处理，解锁也只是让名单里这些回到原始信号 ——"

